// Custom opponents for the Sovereign trials (scripts/evaluate.ts). Legitimate builds from the
// real construction system, each built around a serious idea and free of construction warnings.
// They are test opponents, not starters. Their brains are generated by Configure; the evaluation
// plays every doctrine and reports each opponent at its strongest against Sovereign.
import { DESIGN_SCHEMA_VERSION, type DroneDesign, type MountDesign, type SectionDesign } from '../src/sim/design';

const m = (component: string, rotation = 0, extra: Partial<MountDesign> = {}): MountDesign => ({ component, rotation, ...extra });
const sec = (cls: SectionDesign['class'], layout: SectionDesign['layout'], armor: number, slots: SectionDesign['slots']): SectionDesign => ({ class: cls, layout, armor, slots });
const design = (id: string, name: string, chassis: DroneDesign['chassis'], front: SectionDesign, middle: SectionDesign, rear: SectionDesign): DroneDesign => ({ schema: DESIGN_SCHEMA_VERSION, id, name, chassis, sections: { front, middle, rear } });

export interface Opponent {
  design: DroneDesign;
  /** what it is meant to test */
  idea: string;
}

